Q: Highlight syntax in contenteditable A: <p>I was too lazy to go <em>hardcore</em> with JavaScript and one idea that popped my mind was to use</p>
<ul>
<li>two overlaying DIV elements</li>
<li>the overlaying <strong>contenteditable</strong> has <strong>transparent text</strong> but <strong>visible caret</strong>!</li>
<li>the underlaying DIV is the one that shows the colorful syntax highlighted content</li>
</ul>
<p><strong>PROS</strong></p>
<ul>
<li>The pros about this technique is that you always keep (in the contenteditable DIV) the <strong>unchanged content in its original state</strong>.</li>
</ul>
<p><strong>CONS</strong></p>
<ul>
<li>On every keystroke we parse all over again the same content, and as it gets bigger it might be a performance killer as your replacement list grows <code>O(n)</code></li>
</ul>
<p>For a beautiful read on <strong>optimization</strong> head to <a href="https://code.visualstudio.com/blogs/2017/02/08/syntax-highlighting-optimizations" rel="nofollow noreferrer">VSCode Optimizations in Syntax Highlighting</a></p>
<h3>Basic example:</h3>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const hilite = el =&gt; el.previousElementSibling.innerHTML = (el.value ?? el.textContent)
  .replace(/(&lt;|&gt;|&amp;lt;|&amp;gt;)/g, "&lt;span class='hl-quot-angl'&gt;$1&lt;/span&gt;")
  .replace(/(\{|\})/g, "&lt;span class='hl-quot-curl'&gt;$1&lt;/span&gt;");


document.querySelectorAll(".hilite &gt; *").forEach(el =&gt; {
  el.before(document.createElement("div"));
  el.addEventListener("input", () =&gt; hilite(el));
  hilite(el);
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>.hilite {
  display: grid;
  border: 1px solid #888;
  overflow: auto;

  &gt; * {
    all: unset;
    grid-area: 1 / 1;
    white-space: pre;       
    font-family: monospace;
    overflow: clip;

    &amp;:is(textarea) {
      field-sizing: content;
      min-height: 3lh;
    }

    /* THE UNDERLAYING ONE WITH COLORS */
    &amp;:nth-child(1) {
      user-select: none;
    }

    /* THE OVERLAYING CONTENTEDITABLE WITH TRANSPARENT TEXT */
    &amp;:nth-child(2) {
      color: #0000; /* Text invisible */
      caret-color: black; /* Caret visible */
    }
  }
}

.hl-quot-angl { color: hsl(  0 80% 50%); }
.hl-quot-curl { color: hsl(160 80% 50%); }</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>Try to type angled &amp;lt; &amp;gt; or curly { } brackets

&lt;h3&gt;Contenteditable&lt;/h3&gt;

&lt;div class="hilite"&gt;
  &lt;div contenteditable="plaintext-only"&gt;Type {something} &amp;lt;here&amp;gt;&lt;/div&gt;
&lt;/div&gt;

&lt;h3&gt;Textarea&lt;/h3&gt;

&lt;div class="hilite"&gt;
  &lt;textarea&gt;Type {something} &amp;lt;here&amp;gt;&lt;/textarea&gt;
&lt;/div&gt;

&lt;h3&gt;Input&lt;/h3&gt;

&lt;div class="hilite"&gt;
  &lt;input type="text" value="Type {something} &amp;lt;here&amp;gt;"&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>
<h3>Advanced example:</h3>
<p>(<em>use at your own risk this was my coffee-time playground</em>)</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const lang = {
  js: {
    equa: /(\b=\b)/g,
    quot: /((&amp;#39;.*?&amp;#39;)|(&amp;#34;.*?&amp;#34;)|(".*?(?&lt;!\\)")|('.*?(?&lt;!\\)')|`)/g,
    comm: /((\/\*([^*]|[\r\n]|(\*+([^*/]|[\r\n])))*\*+\/)|(\/\/.*))/g,
    logi: /(%=|%|\-|\+|\*|&amp;amp;{1,2}|\|{1,2}|&amp;lt;=|&amp;gt;=|&amp;lt;|&amp;gt;|!={1,2}|={2,3})/g,
    numb: /(\d+(\.\d+)?(e\d+)?)/g,
    func: /(?&lt;=^|\s*)(async|await|console|alert|Math|Object|Array|String|class(?!\s*\=)|function)(?=\b)/g,
    decl: /(?&lt;=^|\s*)(var|let|const)/g,
    pare: /(\(|\))/g,
    squa: /(\[|\])/g,
    curl: /(\{|\})/g,
  },
  html: {
    tags: /(?&lt;=&amp;lt;(?:\/)?)(\w+)(?=\s|\&amp;gt;)/g,
    // Props order matters! Here I rely on "tags"
    // being already applied in the previous iteration
    angl: /(&amp;lt;\/?|&amp;gt;)/g,
    attr: /((?&lt;=&lt;i class=html_tags&gt;\w+&lt;\/i&gt;)[^&lt;]+)/g,
  }
};

const hilite = el =&gt; {
  const dataLang = el.dataset.lang; // Detect "js", "html", "py", "bash", ...
  const langObj = lang[dataLang]; // Extract object from lang regexes dictionary
  let html = el.innerHTML;
  Object.keys(langObj).forEach(function(key) {
    html = html.replace(langObj[key], `&lt;i class=${dataLang}_${key}&gt;$1&lt;/i&gt;`);
  });
  el.previousElementSibling.innerHTML = html; // Finally, show highlights!
};

const editors = document.querySelectorAll(".hilite .editable");
editors.forEach(el =&gt; {
  el.contentEditable = "plaintext-only";
  el.spellcheck = false;
  el.autocorrect = "off";
  el.autocapitalize = "off";
  el.addEventListener("input", () =&gt; hilite(el));
  hilite(el); // Init!
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>* {margin: 0; box-sizing: boder-box;}

body {
  font: 1rem/1.4 sans-serif;
