const arr = ["high", 'light'];
let n = 2.1 * 3;
if (n &amp;lt; 10) {
  console.log(`${n} is &amp;lt;&amp;#61; than 10`);
}
function casual(str) {
  str = str || "non\"sense";
  alert("Just a casual"+ str +", still many TODOs");
}
casual (arr.join('') +" idea!");

/**
* The code is a proof of concept and far from perfect.
