Q: Handling click events of links rendered within markdown React component A: <p>you can pass the components prop with a mapping of the html elements you want to override.</p>
<pre><code>export const ChatMessageMarkdown = () =&gt; {

function CustomAnchor({
  href,
  children,
  node: _node,
  ...rest
}) {

  return (
    &lt;a
      {...rest}
      title={href}
      href={href}
    &gt;
      {children}
    &lt;/a&gt;
  );
}

  const CUSTOM_MARKDOWN_COMPONENTS = {
    br: () =&gt; &lt;br /&gt;,
    a: CustomAnchor,
  }

  return (
    &lt;MarkdownWrapper&gt;
      &lt;ReactMarkdown
        components={CUSTOM_MARKDOWN_COMPONENTS}
      &gt;
        {displayContent}
      &lt;/ReactMarkdown&gt;
    &lt;/MarkdownWrapper&gt;
  );
};

</code></pre>

